const now = Date.now();
const out = [];
for (const it of items) {
  const inv = it.json || {};
  const status = String(inv.status || '').toLowerCase();
  if (!['sent','overdue','partial'].includes(status)) continue;
  const due = inv.due_date ? Date.parse(inv.due_date) : NaN;
  const overdueDays = Number.isFinite(due) ? Math.floor((now - due) / 86400000) : 0;
  let action = null;
  if (overdueDays >= 30) action = 'reminder_3';
  else if (overdueDays >= 14) action = 'reminder_2';
  else if (overdueDays >= 7) action = 'reminder_1';
  if (action) out.push({ json: { ...inv, _overdue_days: overdueDays, _suggested_action: action } });
}
return out;

const inv = $json;
// Construit un brouillon de relance interne (à valider). Pas de montant côté LLM, on l'injecte tel quel depuis la sheet.
const level = inv._suggested_action;
const client = inv.client_name || 'cher client';
const amount = inv.amount_eur ? `${inv.amount_eur} €` : '[montant]';
const ref = inv.invoice_ref || inv.id || '';
const due = inv.due_date || '[date]';
const tones = {
  reminder_1: { sub: `Relance amicale — facture ${ref}`, body: `Bonjour ${client},

Je me permets un mot rapide concernant la facture ${ref} (${amount}) émise pour échéance au ${due}. Peut-être un oubli — merci de me confirmer si tout est en ordre de votre côté.

Bonne journée,
Arsène – Symbalyx` },
  reminder_2: { sub: `Relance — facture ${ref}`, body: `Bonjour ${client},

Ma précédente relance concernait la facture ${ref} (${amount}). Pourriez-vous me confirmer la prise en compte ou me dire s'il y a un point à clarifier ?

Merci d'avance,
Arsène – Symbalyx` },
  reminder_3: { sub: `Relance ferme — facture ${ref}`, body: `Bonjour ${client},

La facture ${ref} (${amount}) reste impayée alors que l'échéance était le ${due}. Pouvez-vous m'indiquer un délai de règlement, ou me contacter si la facture pose un problème ?

Cordialement,
Arsène – Symbalyx` }
};
const t = tones[level] || tones.reminder_1;
return [{ json: { ...inv, draft_subject: t.sub, draft_body: t.body, requires_human_validation: true } }];
